#include "reachable_from_body/reach.h"

int main(void) {
  struct reach_point point = {1, 2};
  reach_size_t       size  = sizeof(struct reach_point);
  reach_counter += REACH_GREEN;
  return reach_called(&point) + (int)(reach_cast_t)size;
}

